var data = msg.payload || {};
var ppm = Number(data.smoke_ppm || 0);
var temp = Number(data.temp || 0);
var hum = Number(data.hum || 0);
var prevLevel = flow.get('lastAutoLevel') || 'UNKNOWN';
var isManual = flow.get('manualOverride') || false;

var level = 'SAFE';
if (ppm > 600 || temp > 55.0) {
    level = 'DANGER';
} else if (ppm >= 300) {
    level = 'WARNING';
}

if (level === prevLevel) {
    return null;
}

flow.set('lastAutoLevel', level);

if (level === 'DANGER') {
    flow.set('manualOverride', false);
    return [
        [
            { topic: 'nhom12/baokhoi/cmd', payload: JSON.stringify({ cmd: 'FAN_ON' }) },
            { topic: 'nhom12/baokhoi/cmd', payload: JSON.stringify({ buzzer: 1 }) }
        ],
        { payload: { event: 'DANGER_AUTO_TRIGGER', source: 'Rule Engine', smoke_ppm: ppm, temp: temp, hum: hum, action: 'Cháy khẩn cấp -> Tự động BẬT Quạt & Còi 1000Hz' } }
    ];
} else if (level === 'WARNING') {
    var cmds = [];
    if (!isManual) {
        cmds.push({ topic: 'nhom12/baokhoi/cmd', payload: JSON.stringify({ cmd: 'AUTO', buzzer: 0 }) });
    }
    return [
        cmds.length ? cmds : null,
        { payload: { event: 'WARNING_HIGH_SMOKE', source: 'Rule Engine', smoke_ppm: ppm, temp: temp, hum: hum, action: isManual ? 'Khói 300-600 PPM (Giữ Manual)' : 'Khói tăng -> Tự bật quạt tản khói (AUTO)' } }
    ];
} else {
    var safeCmds = [];
    if (!isManual) {
        safeCmds.push({ topic: 'nhom12/baokhoi/cmd', payload: JSON.stringify({ cmd: 'AUTO', buzzer: 0 }) });
    }
    var evName = (prevLevel === 'DANGER' || prevLevel === 'WARNING') ? 'RECOVERY_SAFE' : 'SYSTEM_ONLINE_SAFE';
    var actStr = (evName === 'RECOVERY_SAFE')
        ? (isManual ? 'Hết khói (Giữ trạng thái Manual)' : 'Hết khói -> Trả chế độ AUTO & Tắt còi')
        : 'Kết nối ổn định ở mức An toàn (SAFE)';
    return [
        safeCmds.length ? safeCmds : null,
        { payload: { event: evName, source: 'Rule Engine', smoke_ppm: ppm, temp: temp, hum: hum, action: actStr } }
    ];
}

var d = msg.payload || {};
return {
    payload: {
        event: 'FIRE_ALARM_URGENT',
        source: 'ESP32 Alert Topic',
        smoke_ppm: Number(d.smoke_ppm || 0),
        temp: Number(d.temp || 0),
        hum: Number(d.hum || 0),
        action: 'Nhận gói Alert khẩn cấp (<1s) -> Bắn Telegram'
    }
};

var nowStr = new Date().toLocaleTimeString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });
var wasOffline = (flow.get('deviceOnline') === false);
flow.set('deviceOnline', true);
var d = msg.payload || {};
var statusMsg = { payload: { online: true, lastSeen: nowStr, source: 'HiveMQ SSL 8883' } };
var recMsg = wasOffline
    ? { payload: { event: 'DEVICE_RECONNECTED', source: 'Watchdog', smoke_ppm: Number(d.smoke_ppm || 0), temp: Number(d.temp || 0), hum: Number(d.hum || 0), action: 'ESP32 kết nối lại thành công' } }
    : null;
return [statusMsg, recMsg];

var wasOnline = flow.get('deviceOnline');
if (wasOnline === false && !msg.test) {
    return null;
}
flow.set('deviceOnline', false);
var nowStr = new Date().toLocaleTimeString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });
var evMsg = { payload: { event: 'OFFLINE_TIMEOUT', source: 'Watchdog >20s', smoke_ppm: 0, temp: 0, hum: 0, action: 'Cảnh báo mất kết nối ESP32 quá 20 giây' } };
var statusMsg = { payload: { online: false, lastSeen: nowStr, source: 'Timeout >20s' } };
var tgMsg = { payload: { offline: true, smoke_ppm: 0, temp: 0, hum: 0, time: nowStr } };
return [evMsg, statusMsg, tgMsg];

var d = msg.payload || {};
var ts = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });
var ev = String(d.event || 'EVENT');
var src = String(d.source || 'Middleware');
var ppm = Number(d.smoke_ppm || 0);
var temp = Number(d.temp || 0);
var hum = Number(d.hum || 0);
var act = String(d.action || '').replace(/"/g, "'");

var csvLine = '"' + ts + '",' + ev + ',"' + src + '",' + ppm + ',' + temp + ',' + hum + ',"' + act + '"';

var hist = flow.get('eventHistoryList') || [];
hist.unshift({
    time: ts,
    event: ev,
    source: src,
    ppm: ppm,
    temp: temp,
    action: act
});
if (hist.length > 7) {
    hist = hist.slice(0, 7);
}
flow.set('eventHistoryList', hist);

return [
    { payload: csvLine },
    { payload: hist }
];

var p = msg.payload || {};
var ev = 'USER_ACTION';
var act = 'Thao tác từ Dashboard';
if (p.cmd === 'FAN_ON') {
    flow.set('manualOverride', true);
    ev = 'MANUAL_FAN_ON';
    act = 'Người dùng BẬT Quạt thủ công (Giữ Override)';
} else if (p.cmd === 'FAN_OFF') {
    flow.set('manualOverride', true);
    ev = 'MANUAL_FAN_OFF';
    act = 'Người dùng TẮT Quạt thủ công (Giữ Override)';
} else if (p.cmd === 'AUTO') {
    flow.set('manualOverride', false);
    flow.set('lastAutoLevel', 'UNKNOWN');
    ev = 'SET_AUTO_MODE';
    act = 'Người dùng trả về Chế độ Tự động (AUTO)';
} else if (p.state === 'DANGER') {
    ev = 'TEST_FIRE_750';
    act = 'Kích hoạt nút Test giả lập cháy 750 PPM';
} else if (p.denied) {
    ev = 'AUTH_DENIED_VIEWER';
    act = 'Từ chối thao tác ở quyền Viewer (Chỉ xem)';
}
return {
    payload: {
        event: ev,
        source: 'Dashboard RBAC',
        smoke_ppm: Number(p.smoke_ppm || 0),
        temp: Number(p.temp || 0),
        hum: Number(p.hum || 0),
        action: act
    }
};

var data = msg.payload || {};
var ppm = Number(data.smoke_ppm || 0);
var temp = Number(data.temp || 0);
var hum = Number(data.hum || 0);
var st = data.state || ((ppm > 600 || temp > 55.0) ? 'DANGER' : (ppm >= 300 ? 'WARNING' : 'SAFE'));

var msgPpm = { payload: ppm };
var msgTemp = { payload: temp, topic: 'Nhiệt độ (°C)' };
var msgHum = { payload: hum, topic: 'Độ ẩm (%)' };
var msgEnvCards = { payload: { temp: temp, hum: hum } };
var msgSmokeBadge = { payload: { ppm: ppm, temp: temp, state: st } };

return [msgPpm, msgTemp, msgHum, msgEnvCards, msgSmokeBadge];

var role = (msg.payload === 'VIEWER') ? 'VIEWER' : 'OPERATOR';
flow.set('userRole', role);
if (role === 'VIEWER') {
    return {
        payload: {
            fan: 'CHẾ ĐỘ CHỈ XEM (VIEWER)',
            mode: 'RBAC: Khóa điều khiển',
            color: '#92400e',
            bg: '#fffbeb',
            border: '#fde68a',
            icon: '🔒',
            desc: 'Bạn đang ở quyền Viewer (Chỉ xem). Các nút bật/tắt quạt & giả lập đã bị khóa.'
        }
    };
}
return {
    payload: {
        fan: 'SẴN SÀNG ĐIỀU KHIỂN (OPERATOR)',
        mode: 'RBAC: Toàn quyền',
        color: '#0284c7',
        bg: '#f0f9ff',
        border: '#bae6fd',
        icon: '🔓',
        desc: 'Quyền Operator đang hoạt động: cho phép gửi lệnh Downlink MQTT và Test cháy.'
    }
};

var role = flow.get('userRole') || 'OPERATOR';
var p = msg.payload || {};
if (role === 'VIEWER') {
    var deniedStatus = {
        payload: {
            fan: 'TỪ CHỐI LỆNH (CHỈ XEM)',
            mode: 'RBAC Blocked (Viewer)',
            color: '#b91c1c',
            bg: '#fef2f2',
            border: '#fecdd3',
            icon: '🔒',
            desc: 'Tài khoản Viewer không có quyền điều khiển thiết bị! Chuyển sang Operator để thao tác.'
        }
    };
    return [null, { payload: { denied: true } }, deniedStatus, null];
}

if (p.state === 'DANGER') {
    return [null, msg, msg, msg];
}
return [msg, msg, msg, null];

var p = msg.payload || {};
if (p.fan && p.desc) {
    return msg;
}
var p = msg.payload || {};
if (p.fan && p.desc) {
    return msg;
}
var p = msg.payload || {};
if (p.fan && p.desc) {
    return msg;
}
var p = msg.payload;
if (p.cmd === "FAN_ON") {
    msg.payload = {
        fan: "QUẠT ĐÃ BẬT (ON)",
        mode: "Thủ công (Manual ON)",
        color: "#059669",
        bg: "#ecfdf5",
        border: "#a7f3d0",
        icon: "🌀",
        desc: "✅ Đã gửi lệnh [FAN_ON] xuống ESP32 qua topic nhom12/baokhoi/cmd. Quạt hút đang quay tối đa!"
    };
} else if (p.cmd === "FAN_OFF") {
    msg.payload = {
        fan: "QUẠT ĐÃ TẮT (OFF)",
        mode: "Thủ công (Manual OFF)",
        color: "#e11d48",
        bg: "#fff1f2",
        border: "#fecdd3",
        icon: "⏹️",
        desc: "✅ Đã gửi lệnh [FAN_OFF] xuống ESP32 qua topic nhom12/baokhoi/cmd. Quạt hút đã dừng."
    };
} else if (p.cmd === "AUTO") {
    msg.payload = {
        fan: "CHẾ ĐỘ TỰ ĐỘNG (AUTO)",
        mode: "Tự động (Auto Mode)",
        color: "#0284c7",
        bg: "#f0f9ff",
        border: "#bae6fd",
        icon: "🔄",
        desc: "✅ Đã gửi lệnh [AUTO] xuống ESP32. Hệ thống tự động kích hoạt quạt và còi khi khói > 600 PPM."
    };
} else if (p.state === "DANGER") {
    msg.payload = {
        fan: "QUẠT BẬT TỐI ĐA (CHÁY KHẨN CẤP)",
        mode: "Giả lập khẩn cấp (Test 750 PPM)",
        color: "#dc2626",
        bg: "#fef2f2",
        border: "#fecdd3",
        icon: "🚨",
        desc: "🔥 CẢNH BÁO: Đã kích hoạt kịch bản cháy khẩn cấp 750 PPM. Quạt BẬT, Còi HÚ và đã bắn tin Telegram!"
    };
}
return msg;

var data = msg.payload || {};
var ppm = Number(data.smoke_ppm || 0);
var temp = Number(data.temp || 0);
var lastAlert = context.get('lastAlertTime') || 0;
var now = Date.now();

if ((ppm > 600 || temp > 55.0) && (now - lastAlert > 60000)) {
    context.set('lastAlertTime', now);
    return msg;
}
return null;

var data = msg.payload || {};
var ppm = Number(data.smoke_ppm || 0);
var temp = Number(data.temp || 0);
var hum = Number(data.hum || 0);
var timeStr = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
var CHAT_ID = "YOUR_TELEGRAM_CHAT_ID"; // Chat ID quản trị viên / Nhóm Telegram

var reason = (temp > 55.0 && ppm <= 600) ? 'NHIỆT ĐỘ CAO BẤT THƯỜNG (> 55°C)' : 'NỒNG ĐỘ KHÓI VƯỢT NGƯỠNG (> 600 PPM)';
var messageText = '🚨 <b>[CẢNH BÁO HỎA HOẠN KHẨN CẤP]</b> 🚨\n' +
                  '🏢 <b>Địa điểm:</b> Trạm Cảm Biến Nhóm 12 (Đề tài 04)\n' +
                  '🔥 <b>Nguyên nhân:</b> ' + reason + '\n' +
                  '⚠️ <b>Nồng độ khói:</b> <code>' + ppm + ' PPM</code>\n' +
                  '🌡️ <b>Nhiệt độ:</b> <code>' + temp + ' °C</code> | 💧 <b>Độ ẩm:</b> <code>' + hum + ' %</code>\n' +
                  '🌀 <b>Cơ cấu:</b> Quạt hút BẬT TỐI ĐA | Còi 1000Hz ĐANG HÚ\n' +
                  '⏰ <b>Thời gian:</b> ' + timeStr;

var uiData = { smoke_ppm: ppm, temp: temp, hum: hum, state: 'DANGER', time: timeStr };
return [
    { payload: { chat_id: CHAT_ID, text: messageText, parse_mode: 'HTML' } },
    { payload: uiData }
];

var lastOff = context.get('lastOfflineTg') || 0;
var now = Date.now();
if (now - lastOff < 60000) { return null; }
context.set('lastOfflineTg', now);
var timeStr = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
var CHAT_ID = "YOUR_TELEGRAM_CHAT_ID";
var msgText = '⚠️ <b>[CẢNH BÁO MẤT KẾT NỐI THIẾT BỊ]</b>\n' +
              '📡 Thiết bị ESP32 Nhóm 12 không phản hồi Telemetry quá <b>20 giây</b>!\n' +
              '⏰ <b>Ghi nhận lúc:</b> ' + timeStr + '\n' +
              '👉 <i>Kiểm tra nguồn điện hoặc Wi-Fi/MQTT tại hiện trường.</i>';
return { payload: { chat_id: CHAT_ID, text: msgText, parse_mode: 'HTML' } };

// ====================================================================
// [TẦNG 3 - MIDDLEWARE] BỘ LỌC DỮ LIỆU HỢP LỆ & LOẠI BỎ DỮ LIỆU RÁC
// SV2: Châu Phát Lộc - MSSV: 2001230469
// ====================================================================
// Kiểm tra kịch bản lỗi #2: Loại bỏ dữ liệu rác, không làm sập luồng.
// Quy tắc kiểm tra:
// 1. Payload phải là JSON Object hợp lệ
// 2. Trường smoke_ppm bắt buộc phải là kiểu số (number)
// Nếu vi phạm: Huỷ gói tin (return null), không đưa vào Watchdog & Rule Engine.

if (!msg.payload || typeof msg.payload !== 'object') {
    node.warn('[LỌC DỮ LIỆU RÁC] Loại bỏ gói tin không đúng định dạng JSON: ' + JSON.stringify(msg.payload));
    return null;
}

if (typeof msg.payload.smoke_ppm !== 'number' || isNaN(msg.payload.smoke_ppm)) {
    node.warn('[LỌC DỮ LIỆU RÁC] Loại bỏ gói tin vì smoke_ppm không phải là số (typeof != number): ' + JSON.stringify(msg.payload));
    return null; // Huỷ bỏ an toàn, bảo vệ toàn bộ luồng không bị sập
}

return msg;
